<script setup lang="ts">
import { ref, computed } from 'vue'
import { api } from '../../api'
import { usePage,perform,user } from '../../state'
import { fundTypes,label,requestKey } from '../../domain'
import type { Row,Field } from '../../domain'
import PageHeader from '../../components/PageHeader.vue'
import DataTable from '../../components/DataTable.vue'
import LoadState from '../../components/LoadState.vue'
import OperationForm from '../../components/OperationForm.vue'
import FeeTiers from '../../components/FeeTiers.vue'
const revision=ref<Row|null>(null),revisionReason=ref('')
const funds=ref<Row[]>([]),navs=ref<Row[]>([]),calendar=ref<Row[]>([]),registrars=ref<Row[]>([]),tab=ref('funds'),editor=ref(false),editing=ref<Row|null>(null),initial=ref<Row>({})
const {loading,error,load}=usePage(async()=>{[funds.value,navs.value,calendar.value,registrars.value]=await Promise.all([api.get('/admin/funds'),api.get('/admin/navs'),api.get('/admin/trading-calendar'),api.get('/registrars')])})
const productOptions=computed(()=>funds.value.map(f=>({value:f.id,label:f.name+' · '+f.code})))
const stateOptions=computed(()=>{const state=editing.value?.state;const values=!editing.value?['OPEN','RAISING','DRAFT']:state==='DRAFT'?['DRAFT','RAISING']:state==='BUILDING'?['BUILDING','OPEN']:[state];return values.map(value=>({value,label:label(value)}))})
const fields=computed<Field[]>(()=>[
  {key:'code',label:'基金类别代码'}, {key:'name',label:'产品名称（含A/C类别）'}, {key:'type',label:'投资类型',type:'select',options:fundTypes}, {key:'manager',label:'管理人'},
  {key:'registrarId',label:'登记机构',type:'select',options:registrars.value.map(r=>({value:r.id,label:r.name}))}, {key:'riskLevel',label:'风险等级',type:'select',options:[1,2,3,4,5].map(n=>({value:n,label:'R'+n}))}, {key:'state',label:'运作状态',type:'select',options:stateOptions.value},
  {key:'purchaseRate',label:'申购费率（小数）',hint:'0.015代表1.5%'}, {key:'redemptionRate',label:'赎回基础费率（小数）'}, {key:'minPurchase',label:'最低申购（元）'}, {key:'minRedemption',label:'最低赎回（份）'},
  {key:'purchaseOpen',label:'开放新申购',type:'checkbox',required:false}, {key:'redemptionOpen',label:'开放新赎回',type:'checkbox',required:false}
])
function edit(fund?:Row){editing.value=fund||null;initial.value=fund?{...fund}:{code:'',name:'',type:'MIXED',manager:'恒升模拟基金',registrarId:registrars.value[0]?.id||'',riskLevel:3,state:'OPEN',purchaseRate:'0.0015',redemptionRate:'0.005',minPurchase:'100.00',minRedemption:'1.0000',purchaseOpen:true,redemptionOpen:true};editor.value=true}
async function save(value:Row){const data={...value,registrarId:Number(value.registrarId),riskLevel:Number(value.riskLevel)};return editing.value?api.patch('/admin/funds/'+editing.value.id,data):api.post('/admin/funds',data)}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await perform(async()=>{if(file.size>5*1024*1024)throw new Error('CSV文件不能超过5MB');const data=new FormData();data.append('file',file);return api.post('/admin/navs/import',data)},load);input.value=''}
async function saveRevision(value:Row){revision.value=await api.post('/admin/nav-revisions',{...value,fundClassId:Number(value.fundClassId),requestKey:requestKey()});return revision.value}
async function uploadRevision(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;await perform(async()=>{if(!revisionReason.value.trim())throw new Error('请填写修订原因');if(file.size>5*1024*1024)throw new Error('CSV文件不能超过5MB');const data=new FormData();data.append('file',file);data.append('reason',revisionReason.value);data.append('requestKey',requestKey());revision.value=await api.post('/admin/nav-revisions/import',data);return revision.value});input.value=''}
</script>
<template><PageHeader title="产品与数据" subtitle="维护可交易基金类别、发布净值与开放日期。"><button v-if="tab==='funds'" class="button primary" @click="edit()">＋ 新建基金类别</button><button class="button" @click="load">刷新</button></PageHeader><LoadState :loading="loading" :error="error" @retry="load"/><div class="tabs"><button v-for="t in [['funds','产品规则'],['fees','费用档位'],['navs','净值发布'],['calendar','交易日历'],...(user?.role==='ADMIN'?[['revisions','净值修订']]:[])]" :key="t[0]" :class="{active:tab===t[0]}" @click="tab=t[0]">{{ t[1] }}</button></div><section v-if="tab==='funds'" class="panel"><DataTable :rows="funds" :columns="[{key:'code',label:'代码'}, {key:'name',label:'基金类别'}, {key:'type',label:'类型'}, {key:'riskLevel',label:'风险'}, {key:'state',label:'状态',kind:'state'}, {key:'nav',label:'已公布净值',kind:'nav'}, {key:'purchaseRate',label:'申购费率',kind:'percent'}, {key:'purchaseOpen',label:'申购开放',kind:'bool'}, {key:'redemptionOpen',label:'赎回开放',kind:'bool'}]"><template #actions="{row}"><button v-if="!['TERMINATED','LIQUIDATED','FAILED'].includes(row.state)" class="text-button" @click="edit(row)">维护规则</button><span v-else class="muted small">终态只读</span></template></DataTable></section><FeeTiers v-else-if="tab==='fees'" :funds="funds"/><template v-else-if="tab==='navs'"><div class="grid-two" style="margin-bottom:20px"><OperationForm title="发布日期净值" :fields="[{key:'fundClassId',label:'基金类别',type:'select',options:productOptions},{key:'date',label:'净值所属日期',type:'date'},{key:'nav',label:'单位净值',hint:'最多六位小数；只能使用所属日期的已发布净值'}]" :initial="{fundClassId:funds[0]?.id||'',date:'2026-10-12',nav:''}" :submit="value=>api.post('/admin/navs',{...value,fundClassId:Number(value.fundClassId)})" button="发布净值" @saved="load"/><section class="panel"><h2>批量导入 CSV</h2><p class="muted">列名：fundClassId,date,nav；UTF-8编码，日期YYYY-MM-DD，大小不超过5MB。</p><p class="notice">已影响成交的日期净值不可覆盖；缺少适用净值时等待，不用最近净值替代。</p><label><span>选择净值CSV文件</span><input type="file" accept=".csv,text/csv" @change="upload"/></label></section></div><section class="panel"><h2>已发布净值</h2><DataTable :rows="navs" :columns="[{key:'fundName',label:'产品'}, {key:'fundClassId',label:'类别ID'}, {key:'date',label:'净值日期'}, {key:'nav',label:'单位净值',kind:'nav'}, {key:'status',label:'发布状态',kind:'state'}, {key:'createdAt',label:'发布记录时间',kind:'date'}]"/></section></template><template v-else-if="tab==='revisions'&&user?.role==='ADMIN'"><OperationForm title="保存净值候选修订" :fields="[{key:'fundClassId',label:'基金类别',type:'select',options:productOptions},{key:'marketDate',label:'行情所属日期',type:'date'},{key:'nav',label:'修订单位净值'},{key:'reason',label:'修订原因',type:'textarea'}]" :initial="{fundClassId:funds[0]?.id||'',marketDate:'',nav:'',reason:''}" :submit="saveRevision" button="保存候选修订" description="候选修订先保留原成交与资产，查看影响预演后再执行重新清算。"/><section class="panel"><h2>批量行情修订</h2><p class="muted">CSV列名：fundClassId,date,nav；整个文件作为一组修订预演。</p><label><span>批量修订原因</span><input v-model="revisionReason"/></label><label><span>选择修订CSV文件</span><input type="file" accept=".csv,text/csv" @change="uploadRevision"/></label></section><section v-if="revision" class="panel"><p>候选修订集合 {{ revision.revisionSetId }} 已保存。</p><RouterLink class="button primary" :to="'/admin/trading?revisionSetId='+revision.revisionSetId">查看影响预演</RouterLink></section></template><template v-else><OperationForm title="配置日期开放状态" :fields="[{key:'date',label:'日期',type:'date'}, {key:'open',label:'该日开放交易',type:'checkbox',required:false}]" :initial="{date:'2026-10-12',open:true}" :submit="value=>api.post('/admin/trading-calendar',value)" description="日期必须明确维护；未知日期不会自动视为开放日。" @saved="load"/><section class="panel"><DataTable :rows="calendar" :columns="[{key:'date',label:'日期'}, {key:'open',label:'开放交易',kind:'bool'}, {key:'reason',label:'说明'}]"/></section></template><el-dialog v-model="editor" :title="editing?'维护基金规则':'新建基金类别'" width="750px"><OperationForm title="基金与交易参数" :initial="initial" :fields="fields" :submit="save" @saved="editor=false;load()"/></el-dialog></template>
